import{z as A,x as B,o as e,c as d,q as o,j as s,D as n,d as t,s as r,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"强归纳与结构归纳","description":"","frontmatter":{"title":"强归纳与结构归纳","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/strong-induction.md","filePath":"cs/strong-induction.md","lastUpdated":1791413859000}'),p={name:"cs/strong-induction.md"};function P(c,a,h,m,u,_){const i=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=o('<h1 id="强归纳与结构归纳" tabindex="-1">强归纳与结构归纳 <a class="header-anchor" href="#强归纳与结构归纳" aria-label="Permalink to &quot;强归纳与结构归纳&quot;">​</a></h1><div class="epigraph"><p>有时 $P(n)$ 并不从 $P(n-1)$ 长出来，而从所有更小的实例长出来；公式和树则沿定义的构造规则推。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/mathematical-induction">数学归纳</a>钉死了 \\(P(0)\\) 与 \\(P(k)\\Rightarrow P(k+1)\\)，并点名强归纳与结构归纳，当时不展开。本课不重写自然数梯子，也不从 Peano 另起。缺口是：Fibonacci、摊还里的「拆成更小的两段」、语法树的性质，普通一步假设不够，或对象根本不是 \\(\\mathbb{N}\\) 上的下标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(F_n=F_{n-1}+F_{n-2}\\) 的证明要同时用 \\(P(n-1)\\) 与 \\(P(n-2)\\)。缺口因此不是新的 \\(P\\)，而是强归纳：要证 \\(P(n)\\)，可假设<strong>所有</strong> \\(k\\lt n\\) 已成立（基础仍覆盖最小的若干个）。它与普通归纳在 \\(\\mathbb{N}\\) 上等价，写法不同：当递推宽度大于 \\(1\\) 时，强形式更省事。</p><p><span class="marginnote">强归纳翻译成白话：普通归纳像扶着前一级台阶上楼，强归纳允许踩在已经爬过的所有台阶上——证 P(n) 时，P(0) 到 P(n-1) 全部拿来当已知。两者在自然数上等价，但递推要往后看两步时，普通形式会写不下去。</span></p><p>结构归纳：对象由规则生成（空树；由子树造新树；命题由原子与连接词生成）。对每条规则证：子对象有性质则对象有性质。这不是「对树高做普通归纳」的散文——必须对准定义的条款。后课<a href="/cs/loop-invariant">循环不变式</a>仍是 \\(\\mathbb{N}\\) 上的普通归纳；抽象语法是结构归纳。</p><h3 id="强假设不是免费午餐" tabindex="-1">强假设不是免费午餐 <a class="header-anchor" href="#强假设不是免费午餐" aria-label="Permalink to &quot;强假设不是免费午餐&quot;">​</a></h3><p>基础步往往要写 \\(P(0)\\) 与 \\(P(1)\\)，或所有最小构造。漏掉第二条规则（空表、空树），整棵倒掉。在归纳步里调用 \\(P(n)\\) 自身，仍是循环论证。</p><p><span class="marginnote">常见误区：以为强归纳只需基础步 P(0)。递推宽度是 2（如 Fibonacci）时，归纳步要引用 P(n-2)，所以 P(0) 与 P(1) 都得单独立住——少证一个，整座塔从第二层开始就是空的。</span></p><p><span class="marginnote">Rosen 把强归纳与「完全归纳」对照，并用递归定义的公式做结构归纳。后课图若无环，可沿拓扑序做归纳；有环则结构归纳的「子对象更小」先要另找良基关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写清 \\(P(n)\\)。强归纳：固定 \\(n\\)，假设 \\(\\forall k\\lt n\\,P(k)\\)，证 \\(P(n)\\)；检查 \\(n\\) 较小时不引用不存在的前项。结构归纳：按定义分情形，每情形只引用真子结构。</p>',13)),(e(),s(l,null,{default:n(()=>[r(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20WEAK%5B%22%E6%99%AE%E9%80%9A%EF%BC%9AP(k)%20%E2%87%92%20P(k%2B1)%22%5D%20--%3E%20STR%5B%22%E5%BC%BA%EF%BC%9A%E5%85%A8%E4%BD%93%E6%9B%B4%E5%B0%8F%22%5D%0A%20%20STR%20--%3E%20ST%5B%22%E7%BB%93%E6%9E%84%EF%BC%9A%E6%B2%BF%E6%9E%84%E9%80%A0%E8%A7%84%E5%88%99%22%5D%0A%20%20ST%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%B8%BD%E7%AC%BC%E6%98%AF%E5%AD%98%E5%9C%A8%E6%80%A7%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"递归程序的正确性：参数在某良基序上变小，对那个序做强归纳或结构归纳。后课树高、表达式求值、合式公式的唯一读法，都走结构归纳。渐近记号仍未进场：归纳证的是「对每个 \\(n\\) 成立」，不自动给出 \\(O\\)。",-1)),(e(),s(l,null,{default:n(()=>[r(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20FN%5B%22%E8%A6%81%E8%AF%81%20P(n)%EF%BC%9AFibonacci%20%E9%80%92%E6%8E%A8%22%5D%20--%3E%20P1%5B%22%E9%9C%80%E8%A6%81%20P(n-1)%20%E6%88%90%E7%AB%8B%22%5D%0A%20%20FN%20--%3E%20P2%5B%22%E4%B9%9F%E9%9C%80%E8%A6%81%20P(n-2)%20%E6%88%90%E7%AB%8B%22%5D%0A%20%20P1%20--%3E%20HYP%5B%22%E6%99%AE%E9%80%9A%E5%BD%92%E7%BA%B3%E5%8F%AA%E6%9C%89%20P(n-1)%EF%BC%9A%E4%B8%8D%E5%A4%9F%E7%94%A8%22%5D%0A%20%20P2%20--%3E%20HYP%0A%20%20HYP%20--%3E%20SI%5B%22%E5%BC%BA%E5%BD%92%E7%BA%B3%EF%BC%9A%E5%81%87%E8%AE%BE%E6%89%80%E6%9C%89%E6%9B%B4%E5%B0%8F%E7%9A%84%20k%20%E9%83%BD%E6%88%90%E7%AB%8B%22%5D%0A%20%20SI%20--%3E%20BASE%5B%22%E5%9F%BA%E7%A1%80%E6%AD%A5%E5%8D%95%E7%8B%AC%E7%AB%8B%E4%BD%8F%20P(0)%20%E4%B8%8E%20P(1)%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">直觉类比：结构归纳像验收积木楼——不去数楼层，而是检查每种拼装规则：单块积木合格吗？两摞合格的楼拼起来还合格吗？规则条条过关，所有能拼出来的楼就都合格，包括还没拼的那些。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入序数、超限归纳。鸽笼、容斥是后面的计数工具，不是归纳格式的替代。也不把数学归纳与自然科学的「归纳推理」混名。</p><p>后课默认：递推宽度大于 \\(1\\) 用强归纳；递归数据类型用结构归纳。存在性计数下一课才换工具。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>强归纳允许使用所有更小实例；基础要盖住递推宽度。</li><li>结构归纳对准递归定义的每条规则。</li><li>正确性归纳仍不代替代价；鸽笼是另一条存在原理。</li><li>出处：Rosen, <em>Discrete Mathematics and Its Applications</em>。</li></ul>',6))])}const f=A(p,[["render",P]]);export{b as __pageData,f as default};
